//! The build half of the runtime route: four modules and two generated files.
//!
//! An SDK that ships the runtime route calls `createModule` in place of
//! `translate.createModule()` and imports what comes back as its `c` module.
//! Nothing here links a native archive. That is the point: in this
//! configuration every `s2br_*` symbol arrives through the platform loader at
//! run time, and linking `libs2bridge` as well would make the linker demand
//! them before `load` ever runs.
//!
//!   rt        runtime/loader.zig, the reusable core, supplied by the driver.
//!             Pure Zig; imported by the facade in both configurations, because
//!             `LoadSource` and `LoadError` are this SDK's public types and must
//!             be the same types whichever configuration is built.
//!   library   runtime/library.zig, this SDK's descriptor: the namespaced
//!             synchronization binding and the load-time checks.
//!   dispatch  generated by runtime/generate.zig from the real translation
//!             output: the table, the wrappers, `load`, and the re-exported
//!             translated namespace. It imports `rt`, `library` and the
//!             patched translation as `c_native`.
//!   native    the generator's second file: the same translation with the
//!             `__root` prologue Aro writes replaced by an import of the
//!             dispatch as `c_routed`, so a declaration nested inside a
//!             translated type names the routed wrapper rather than the raw
//!             extern. It imports the dispatch and nothing else.
//!   sync.c    compiled into the dispatch with
//!             `-DRT_SYNC_PREFIX=s2geometry_rt`, so its symbols cannot collide
//!             with another SDK's.
//!
//! ## What the provider is, and why it is not `libs2`
//!
//! The whole routed surface is this fork's own C bridge: 93 entry points, every
//! one of them defined in `zig/bridge.cc`. An upstream `libs2` at any version
//! exports **none** of them, because upstream has no such header
//! (`zig/bridge.h:11-17` says why the bridge exists at all: `addTranslateC`
//! translates C, and S2 is C++17). So a loaded provider for this SDK is a shared
//! `libs2bridge.so.0` -- or `.dylib`, or `s2bridge.dll` -- whose own
//! `DT_NEEDED` closure carries `libs2.so.0` and, through it, `libabsl.so.2508`.
//! Naming an installed `libs2.so` instead is refused with `MissingSymbol` on
//! the first `s2br_*` lookup, which is the honest answer: it is not a provider
//! for this header, and `runtime/library.zig` writes out the whole boundary.
//!
//! ## What this module deliberately does not do
//!
//! It links nothing native. It does not add Abseil's or S2's include roots to a
//! link line, does not name `libs2bridge`, and does not call
//! `linkSystemLibrary`. If a runtime-loading build ever fails to link because
//! `s2br_cell_from_lat_lng_deg` is undefined, something other than this file
//! added that library to the graph -- this one has no path by which it could.
//!
//! It also does not decide anything about targets. `wasm32-wasi` builds this
//! dispatch and the loader core exactly like any other target; the loader core
//! answers every request there with `UnsupportedTarget`, because WASI has no
//! `dlopen` (`runtime/loader.zig`, `supported_target`). That refusal is the
//! loader's, it happens at run time, and it is not a reason to exclude WASI
//! from the graph: WASI stays a fully supported target for the linked
//! configuration, which is the default.

const std = @import("std");

const absl_sources = @import("../build_support/absl_sources.zig");
const s2_sources = @import("../build_support/s2_sources.zig");

/// The prefix `runtime/sync.c` is compiled with.
///
/// `runtime/library.zig` declares the same prefix in the symbol names it binds.
/// The two must agree, and a build where they do not fails to link, which is
/// the whole error report: there is no runtime path that could hide it.
///
/// A build that needs a second, independent instance of this SDK in one binary
/// should change this value *and* the prefix in `runtime/library.zig`, and then
/// give the second instance its own copy of both files. Nothing else in the
/// package assumes one instance.
const sync_prefix = "s2geometry_rt";

/// `extern` declarations that the C library provides and that must therefore
/// stay direct.
///
/// ## What this list holds, and why it is so short
///
/// `zig/bridge.h:92-93` includes exactly two headers before its `extern "C"`
/// block: `<stddef.h>` and `<stdint.h>`. That was read out of the pinned Zig
/// 0.16.0 libc headers rather than assumed:
///
///   * `lib/libc/include/generic-musl/stddef.h`, `.../any-darwin-any/stddef.h`
///     and `.../any-windows-any/stddef.h` declare types, macros and `NULL` only.
///   * `lib/libc/include/generic-musl/stdint.h`, `.../generic-glibc/stdint.h`,
///     `.../generic-freebsd/stdint.h`, `.../generic-netbsd/stdint.h`,
///     `.../generic-openbsd/stdint.h`, `.../any-darwin-any/stdint.h` and
///     `.../any-windows-any/stdint.h` declare the fixed-width typedefs and the
///     limit macros only.
///
/// So on glibc, musl, Darwin, FreeBSD, NetBSD and OpenBSD the translated bridge
/// declares 93 `extern` functions, every one of them `s2br_*` or
/// `S2BRIDGE_*`, and there is no C library declaration for the generator to
/// mistake for one. A mingw-w64 target is the exception, and the measurement
/// is what found it: `<stdint.h>` reaches `_mingw.h` through `stdint.h:32`,
/// `stddef.h:7`, `crtdefs.h:10` and `corecrt.h:10`, and that header declares
/// `__prefetch` (`_mingw.h:650`, arm and aarch64 only) and
/// `__mingw_get_crt_info` (`_mingw.h:665`). `zig/bridge.h` was translated with
/// the pinned Zig 0.16.0 for every target in the matrix and every name that was
/// not a bridge name was read out of the output: these two, and nothing else
/// (`SOURCE-CONFIRMED`, 2026-10-04). Ten targets - the nine NetBSD ones and
/// `powerpc64le-openbsd` - produced no C library header the sweep could
/// classify, and no name here is claimed for either.
///
/// The two consequences are both deliberate:
///
///   * The list below is those two names, so nothing else is quietly kept
///     direct. Were a libc name listed here and a future bridge header also
///     declared something spelled that way, the bridge's own symbol would stop
///     being resolved at load time -- a silent hole.
///   * If a bridge header ever reaches `<string.h>`, `<stdlib.h>` or
///     `<math.h>`, this is the line that has to grow, and it is a build-file
///     change with a name in it rather than a load that fails with
///     `MissingSymbol` on `memcpy`.
const libc_noise =
    \\__mingw_get_crt_info,__prefetch
;

/// `extern` declarations the provider may legitimately not export.
///
/// None, and that is a source fact rather than an omission. `zig/bridge.h`
/// declares 93 entry points and `zig/bridge.cc` defines 93: 88 returning
/// `S2BridgeStatus`, three `int` total functions (`s2br_cell_is_valid`,
/// `s2br_cell_is_leaf`, `s2br_cell_is_face`) and two `void` frees
/// (`s2br_loop_destroy`, `s2br_polygon_destroy`). Comparing the two sets of
/// names leaves nothing on either side. There is also no configuration-dependent
/// declaration and no exported data symbol: `S2BRIDGE_MAX_LEVEL` is a macro, so
/// it is a translated constant rather than an object the provider would have to
/// export, and nothing else in the header is an `extern` variable.
const provider_optional = "";

/// `extern` declarations this build does not require from a provider.
///
/// None. Every one of the 93 bridge entry points is expected from a provider,
/// and a provider that does not export one of them is refused rather than half
/// used. A name here would be routed into a nullable table field instead: its
/// absence would not fail the load, and its wrapper would stop the program by
/// name. Only `libc_noise` above keeps a declaration direct.
const provider_excluded = "";

/// The loader core, for a *linked* build to import.
///
/// A linked build has no dispatch, so the facade needs the core module itself
/// for the two public types `LoadSource` and `LoadError`: they are this SDK's
/// types and they must be the same types a caller names in either
/// configuration. It costs a linked build two declarations and no code, since
/// nothing else in that module is referenced until a configuration actually
/// instantiates the loader.
///
/// A runtime-loading build must *not* import this separately: `createModule`
/// makes the one core instance the dispatch uses, and the dispatch re-exports
/// the two types from it. Two instances would be two sets of types, and a
/// consumer would be naming one while `load` expects the other.
pub fn createCoreModule(
    b: *std.Build,
    target: std.Build.ResolvedTarget,
    optimize: std.builtin.OptimizeMode,
) *std.Build.Module {
    return b.createModule(.{
        .root_source_file = b.path("runtime/loader.zig"),
        .target = target,
        .optimize = optimize,
        // The Unix backend calls `dlopen`, which is libc. Nothing in this module
        // is compiled into a linked build, so this costs nothing there.
        .link_libc = true,
    });
}

/// The runtime-loaded `c` module for one target.
///
/// `translate` is the translation step for that same target and configuration;
/// its output is read by the generator, so the dispatch describes the header
/// this build actually selected rather than another one. The bundled graph and
/// the `-fsys=s2` graph both pass their own step, and both translate the same
/// `zig/bridge.h`, so both produce the same 93 routed names.
///
/// The two upstream include roots go back onto the returned module and onto the
/// `c_native` module. Neither reaches a module on its own - the include paths
/// belong to the translation step, not to a module built from its output - and
/// the linked branch puts the same two paths on its `c` module
/// (`build.zig`, `addGraph`), so the runtime branch resolves the same header
/// environment the linked one does.
///
/// Anything target-specific the caller owns -- the external WASI sysroot roots
/// and its threading model -- is applied by the caller to the module this
/// returns, exactly as `addGraph` already applies it to its own `c` module. That
/// sysroot is a build option declared once in `build.zig`, and
/// `std.Build.option` panics when the same name is declared twice
/// (`lib/std/Build.zig:1162-1164`), so this file cannot and does not declare it
/// a second time.
pub fn createModule(
    b: *std.Build,
    translate: *std.Build.Step.TranslateC,
    target: std.Build.ResolvedTarget,
    optimize: std.builtin.OptimizeMode,
) *std.Build.Module {
    const core = createCoreModule(b, target, optimize);

    const library = b.createModule(.{
        .root_source_file = b.path("runtime/library.zig"),
        .target = target,
        .optimize = optimize,
    });
    library.addImport("rt", core);

    return createDispatchModule(b, translate, target, optimize, core, library);
}

/// What one generator run writes: the dispatch, and the translation it reads.
const GeneratedSources = struct {
    native: std.Build.LazyPath,
    dispatch: std.Build.LazyPath,
};

fn createDispatchModule(
    b: *std.Build,
    translate: *std.Build.Step.TranslateC,
    target: std.Build.ResolvedTarget,
    optimize: std.builtin.OptimizeMode,
    core: *std.Build.Module,
    library: *std.Build.Module,
) *std.Build.Module {
    const sources = generateDispatch(b, translate, target);

    // The patched translation, under a name that says what it is. Every type and
    // constant in the dispatch is re-exported from here rather than restated, so
    // `c.S2BridgeLoop` in a facade and `c_native.S2BridgeLoop` in the dispatch
    // are one nominal type, and `c_routed` is what makes the members nested
    // inside those types the routed wrappers.
    const native = b.createModule(.{
        .root_source_file = sources.native,
        .target = target,
        .optimize = optimize,
        .link_libc = true,
    });
    addUpstreamIncludePaths(b, native);

    const dispatch = b.createModule(.{
        .root_source_file = sources.dispatch,
        .target = target,
        .optimize = optimize,
        .link_libc = true,
    });
    dispatch.addImport("rt", core);
    dispatch.addImport("library", library);
    dispatch.addImport("c_native", native);
    native.addImport("c_routed", dispatch);
    addUpstreamIncludePaths(b, dispatch);
    dispatch.addCSourceFiles(.{
        .files = &.{"runtime/sync.c"},
        .flags = &.{b.fmt("-DRT_SYNC_PREFIX={s}", .{sync_prefix})},
        .language = .c,
    });
    return dispatch;
}

/// The same two include roots the linked branch puts on its `c` module.
///
/// `zig/bridge.h` names no upstream type at this pin, so nothing in it is
/// resolved from either root today. They are here because a bridge header is
/// allowed to name one -- that is the reason the linked branch already carries
/// them -- and a translation that could not resolve it would describe an
/// interface the compiled bridge does not implement.
fn addUpstreamIncludePaths(b: *std.Build, module: *std.Build.Module) void {
    module.addIncludePath(b.path(s2_sources.include_dir));
    module.addIncludePath(b.path(absl_sources.include_dir));
}

/// Runs the generator over the translation step's real output.
///
/// The generator is a host program built and run by this build, so the dispatch
/// is produced for the target being built from that target's own translation.
/// Nothing is cached across configurations: a different header configuration
/// produces a different translation step output, which produces a different
/// dispatch.
fn generateDispatch(
    b: *std.Build,
    translate: *std.Build.Step.TranslateC,
    target: std.Build.ResolvedTarget,
) GeneratedSources {
    const generator = b.addExecutable(.{
        .name = b.fmt("s2geometry-runtime-generate-{s}", .{
            target.result.zigTriple(b.allocator) catch @panic("unspellable target"),
        }),
        .root_module = b.createModule(.{
            .root_source_file = b.path("runtime/generate.zig"),
            .target = b.graph.host,
            .optimize = .Debug,
        }),
    });

    const run = b.addRunArtifact(generator);
    run.addArg("--library");
    run.addArg("s2geometry");
    run.addArg("--translate");
    run.addFileArg(translate.getOutput());
    if (libc_noise.len != 0) {
        run.addArg("--noise");
        run.addArg(libc_noise);
    }
    if (provider_optional.len != 0) {
        run.addArg("--optional");
        run.addArg(provider_optional);
    }
    if (provider_excluded.len != 0) {
        run.addArg("--exclude");
        run.addArg(provider_excluded);
    }
    run.addArg("--native-output");
    const native_source = run.addOutputFileArg("native.zig");
    run.addArg("--output");
    const dispatch_source = run.addOutputFileArg("dispatch.zig");
    return .{ .native = native_source, .dispatch = dispatch_source };
}